package com.openminis.app.data.db

import com.openminis.app.offload.AgentBoardLogic
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File
import java.sql.Connection
import java.sql.DriverManager
import java.sql.SQLException
import java.util.concurrent.CountDownLatch
import java.util.concurrent.atomic.AtomicInteger

/**
 * [T-board-terminal-write] The contract of a run's terminal write, proved
 * on a REAL SQLite engine.
 *
 * The app's DAO is generated by Room, which needs a device, and this
 * project has no Robolectric and no emulator - so the question "does the
 * guarded update actually guard?" was previously unanswerable here. The
 * project already tests against real SQLite through the JDBC driver, and
 * that is enough: the part that could be wrong is the SQL and the
 * transaction boundary, and both are exercised below.
 *
 * What this covers:
 *  - the exact UPDATE the app runs (the same constant, not a copy),
 *  - the rule that a losing completion writes nothing at all,
 *  - rollback when the write fails in the middle,
 *  - the decision that tells a cancellation from a failure.
 *
 * What this does NOT cover: Room's own code generation, the entity mapping,
 * and the @Transaction wiring in the app itself. Those are compile-time
 * artefacts - Room's annotations are retained at CLASS level and are not
 * visible at runtime, so no reflection can check them here. The only honest
 * proof for those is a device.
 *
 * What IS covered structurally: the app and this test run the same SQL
 * constant, so they cannot drift apart. And the guarded update is the one
 * the app executes - the guard is inside the constant, not beside it.
 */
class AgentBoardTerminalWriteTest {

    /**
     * A stand-in for AgentBoardDao.finishTask: the same guarded update,
     * the same "nothing happens unless the move happened" rule, inside one
     * transaction.
     */
    private class Board(private val conn: Connection) {
        /**
         * Returns true when this call is the one that finished the task.
         */
        fun finish(
            taskId: String,
            from: String,
            to: String,
            result: String,
            failMidway: Boolean = false,
        ): Boolean {
            conn.autoCommit = false
            try {
                val ps = conn.prepareStatement(SQL_SET_STATUS_IF)
                ps.setString(1, to)
                ps.setLong(2, 1_700_000_000_000L)
                ps.setString(3, taskId)
                ps.setString(4, from)
                val changed = ps.executeUpdate()
                ps.close()
                if (changed == 0) {
                    conn.rollback()
                    return false
                }
                conn.prepareStatement(
                    "INSERT INTO task_status_history(task_id, from_status, to_status, reason) " +
                        "VALUES(?,?,?,?)",
                ).use { h ->
                    h.setString(1, taskId)
                    h.setString(2, from)
                    h.setString(3, to)
                    h.setString(4, "reason")
                    h.executeUpdate()
                }
                conn.prepareStatement(
                    "UPDATE agent_tasks SET result_artifact = ? WHERE id = ?",
                ).use { r ->
                    r.setString(1, result)
                    r.setString(2, taskId)
                    r.executeUpdate()
                }
                conn.prepareStatement(
                    "INSERT INTO agent_mailbox(task_id, message_type, body) VALUES(?,?,?)",
                ).use { m ->
                    m.setString(1, taskId)
                    m.setString(2, "result")
                    m.setString(3, result)
                    m.executeUpdate()
                }
                if (failMidway) throw IllegalStateException("boom")
                conn.commit()
                return true
            } catch (t: Throwable) {
                conn.rollback()
                throw t
            } finally {
                conn.autoCommit = true
            }
        }
    }

    private fun withBoard(block: (Board, Connection) -> Unit) {
        // A plain file path, not a directory: SQLite creates the database
        // file itself. createTempFile() would return a file that had to be
        // deleted to be used as a directory, and the driver would then fail
        // to open a path whose parent does not exist.
        val file = File(
            System.getProperty("java.io.tmpdir") ?: "/tmp",
            "board-test-${System.nanoTime()}.db",
        )
        val conn = DriverManager.getConnection("jdbc:sqlite:${file.absolutePath}")
        try {
            conn.createStatement().use { s ->
                s.executeUpdate("PRAGMA busy_timeout = 5000")
                s.executeUpdate(
                    "CREATE TABLE agent_tasks(" +
                        "id TEXT PRIMARY KEY, status TEXT NOT NULL, " +
                        "result_artifact TEXT, updated_at INTEGER)",
                )
                s.executeUpdate(
                    "CREATE TABLE task_status_history(" +
                        "task_id TEXT, from_status TEXT, to_status TEXT, reason TEXT)",
                )
                s.executeUpdate(
                    "CREATE TABLE agent_mailbox(" +
                        "task_id TEXT, message_type TEXT, body TEXT)",
                )
            }
            conn.prepareStatement("INSERT INTO agent_tasks(id, status) VALUES(?,?)").use {
                it.setString(1, "task-1")
                it.setString(2, AgentBoardLogic.STATUS_RUNNING)
                it.executeUpdate()
            }
            block(Board(conn), conn)
        } finally {
            conn.close()
            file.delete()
        }
    }

    private fun statusOf(conn: Connection): String =
        conn.createStatement().use { s ->
            s.executeQuery("SELECT status FROM agent_tasks WHERE id = 'task-1'").use { rs ->
                rs.next()
                rs.getString(1)
            }
        }

    private fun count(conn: Connection, table: String): Int =
        conn.createStatement().use { s ->
            s.executeQuery("SELECT COUNT(*) FROM $table").use { rs ->
                rs.next()
                rs.getInt(1)
            }
        }

    private fun resultOf(conn: Connection): String? =
        conn.createStatement().use { s ->
            s.executeQuery("SELECT result_artifact FROM agent_tasks WHERE id = 'task-1'").use { rs ->
                rs.next()
                rs.getString(1)
            }
        }

    // 1. Первый успешный finish: один статус, один результат, одно письмо, одно событие.
    @Test
    fun `the first successful finish writes everything exactly once`() = withBoard { board, conn ->
        val won = board.finish("task-1", AgentBoardLogic.STATUS_RUNNING, AgentBoardLogic.STATUS_COMPLETED, "the result")

        assertTrue("the first finish must win", won)
        assertEquals(AgentBoardLogic.STATUS_COMPLETED, statusOf(conn))
        assertEquals("the result", resultOf(conn))
        assertEquals(1, count(conn, "task_status_history"))
        assertEquals(1, count(conn, "agent_mailbox"))
    }

    // 2. Повторный finish: никаких новых побочных записей.
    @Test
    fun `a second finish writes nothing at all`() = withBoard { board, conn ->
        board.finish("task-1", AgentBoardLogic.STATUS_RUNNING, AgentBoardLogic.STATUS_COMPLETED, "first")
        val second = board.finish("task-1", AgentBoardLogic.STATUS_RUNNING, AgentBoardLogic.STATUS_FAILED, "second")

        assertTrue("a repeated finish must not win", !second)
        assertEquals("the first result must survive", "first", resultOf(conn))
        assertEquals(1, count(conn, "task_status_history"))
        assertEquals(1, count(conn, "agent_mailbox"))
    }

    // 3. КОНКУРЕНЦИЯ: два потока стартуют одновременно по барьеру.
    //
    // Последовательные вызовы проверяли бы идемпотентность, а не гонку.
    // Здесь оба потока стартуют по одному барьеру и пишут в одну базу из
    // двух соединений, поэтому проигравший видит уже изменённый статус -
    // ровно та гонка, ради которой переход и был защищён.
    @Test
    fun `of two genuinely concurrent finishes only one may write`() {
        val file = File(
            System.getProperty("java.io.tmpdir") ?: "/tmp",
            "board-race-${System.nanoTime()}.db",
        )
        val setup = DriverManager.getConnection("jdbc:sqlite:${file.absolutePath}")
        try {
            setup.createStatement().use { s ->
                s.executeUpdate("PRAGMA busy_timeout = 5000")
                s.executeUpdate(
                    "CREATE TABLE agent_tasks(" +
                        "id TEXT PRIMARY KEY, status TEXT NOT NULL, " +
                        "result_artifact TEXT, updated_at INTEGER)",
                )
                s.executeUpdate(
                    "CREATE TABLE task_status_history(" +
                        "task_id TEXT, from_status TEXT, to_status TEXT, reason TEXT)",
                )
                s.executeUpdate(
                    "CREATE TABLE agent_mailbox(" +
                        "task_id TEXT, message_type TEXT, body TEXT)",
                )
            }
            setup.prepareStatement("INSERT INTO agent_tasks(id, status) VALUES(?,?)").use {
                it.setString(1, "task-1")
                it.setString(2, AgentBoardLogic.STATUS_RUNNING)
                it.executeUpdate()
            }
        } finally {
            setup.close()
        }

        val a = DriverManager.getConnection("jdbc:sqlite:${file.absolutePath}")
        val b = DriverManager.getConnection("jdbc:sqlite:${file.absolutePath}")
        try {
            listOf(a, b).forEach { c ->
                c.createStatement().use { it.executeUpdate("PRAGMA busy_timeout = 5000") }
            }
            val start = CountDownLatch(1)
            val winners = AtomicInteger(0)

            fun racer(conn: Connection, to: String, payload: String) = Thread {
                start.await()
                try {
                    if (Board(conn).finish("task-1", AgentBoardLogic.STATUS_RUNNING, to, payload)) {
                        winners.incrementAndGet()
                    }
                } catch (e: SQLException) {
                    // SQLite refused the write outright because the other
                    // transaction held the lock. That is a loss too: this
                    // caller did not write anything.
                }
            }

            val t1 = racer(a, AgentBoardLogic.STATUS_COMPLETED, "ok")
            val t2 = racer(b, AgentBoardLogic.STATUS_FAILED, "boom")
            t1.start()
            t2.start()
            start.countDown()
            t1.join(10_000)
            t2.join(10_000)

            assertEquals("exactly one of the two concurrent finishes may write", 1, winners.get())
            val reader = DriverManager.getConnection("jdbc:sqlite:${file.absolutePath}")
            try {
                assertEquals("the ledger must hold exactly one move", 1, count(reader, "task_status_history"))
                assertEquals("the spawning session must get exactly one letter", 1, count(reader, "agent_mailbox"))
                val status = statusOf(reader)
                assertTrue(
                    "the surviving status must be one of the two outcomes, was $status",
                    status == AgentBoardLogic.STATUS_COMPLETED || status == AgentBoardLogic.STATUS_FAILED,
                )
                val stored = resultOf(reader)
                assertTrue(
                    "the stored result must belong to the winner, was $stored",
                    stored == "ok" || stored == "boom",
                )
            } finally {
                reader.close()
            }
        } finally {
            a.close()
            b.close()
            file.delete()
        }
    }

    // 4. Отмена против успешного завершения: один согласованный исход.
    @Test
    fun `a cancellation and a success cannot both win`() = withBoard { board, conn ->
        val cancelled = board.finish("task-1", AgentBoardLogic.STATUS_RUNNING, AgentBoardLogic.STATUS_CANCELLED, "stopped")
        val completed = board.finish("task-1", AgentBoardLogic.STATUS_RUNNING, AgentBoardLogic.STATUS_COMPLETED, "ok")

        assertTrue(cancelled)
        assertTrue("the losing outcome must not write", !completed)
        assertEquals(AgentBoardLogic.STATUS_CANCELLED, statusOf(conn))
        assertEquals(1, count(conn, "agent_mailbox"))
    }

    // 5. Ошибка внутри транзакции: полный rollback.
    @Test
    fun `a failure inside the transaction rolls everything back`() = withBoard { board, conn ->
        var thrown = false
        try {
            board.finish("task-1", AgentBoardLogic.STATUS_RUNNING, AgentBoardLogic.STATUS_COMPLETED, "x", failMidway = true)
        } catch (t: IllegalStateException) {
            thrown = true
        }

        assertTrue("the failure must propagate", thrown)
        assertEquals("the status must be rolled back", AgentBoardLogic.STATUS_RUNNING, statusOf(conn))
        assertEquals("the result must be rolled back", null, resultOf(conn))
        assertEquals("the ledger must be rolled back", 0, count(conn, "task_status_history"))
        assertEquals("the letter must be rolled back", 0, count(conn, "agent_mailbox"))
    }

    // 6. Отмена не превращается в обычную ошибку.
    @Test
    fun `a cancellation is reported as cancelled, not as a failure`() {
        val outcome = AgentBoardLogic.terminalOutcome(succeeded = false, cancelled = true)

        assertEquals(AgentBoardLogic.STATUS_CANCELLED, outcome.status)
        assertEquals("cancelled", outcome.reason)
        assertEquals("cancelled", outcome.messageType)
        assertEquals("RUN_CANCELLED", outcome.eventType)
        assertNotEquals(AgentBoardLogic.STATUS_FAILED, outcome.status)
    }

    // 7. Обычное исключение: FAILED, а не CANCELLED.
    @Test
    fun `an ordinary failure is reported as failed, not as a cancellation`() {
        val outcome = AgentBoardLogic.terminalOutcome(succeeded = false, cancelled = false)

        assertEquals(AgentBoardLogic.STATUS_FAILED, outcome.status)
        assertEquals("failed", outcome.reason)
        assertEquals("error", outcome.messageType)
        assertEquals("RUN_FAILED", outcome.eventType)
        assertNotEquals(AgentBoardLogic.STATUS_CANCELLED, outcome.status)
    }

    // 8. Успех — это COMPLETED, и никакой отмены.
    @Test
    fun `a success is completed`() {
        val outcome = AgentBoardLogic.terminalOutcome(succeeded = true, cancelled = false)

        assertEquals(AgentBoardLogic.STATUS_COMPLETED, outcome.status)
        assertEquals("completed", outcome.reason)
        assertEquals("result", outcome.messageType)
        assertEquals("RUN_COMPLETED", outcome.eventType)
    }

    // 9. Противоречивые входные данные: приоритет зафиксирован, а не случаен.
    @Test
    fun `a run that is both successful and cancelled resolves to one documented status`() {
        val outcome = AgentBoardLogic.terminalOutcome(succeeded = true, cancelled = true)

        // The contract is that cancellation wins: a run the user stopped did
        // not run to completion, whatever the caller believes about it. The
        // point of the test is that the answer is fixed, not that it is any
        // particular value.
        assertEquals(AgentBoardLogic.STATUS_CANCELLED, outcome.status)
        assertEquals("cancelled", outcome.reason)
        assertEquals("cancelled", outcome.messageType)
        assertEquals("RUN_CANCELLED", outcome.eventType)
    }

    // 10. Общий SQL - это СТРУКТУРНАЯ гарантия, а не проверка копии.
    //
    // Приложение и тест ссылаются на одну константу, поэтому разойтись они
    // не могут: если константа изменится, изменится и запрос в приложении.
    // Проверяем, что эта общая константа действительно несёт гард.
    @Test
    fun `the shared query carries the guard`() {
        val sql = AgentBoardDao.SQL_SET_STATUS_IF

        assertTrue(
            "the shared query must be conditional on the current status",
            sql.contains("AND status = :from"),
        )
        assertTrue(
            "the shared query must be bound to one task",
            sql.contains("WHERE id = :taskId"),
        )
    }
}
